import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int k = Integer.parseInt(scanner.nextLine()); // 输入正整数K
        String s = scanner.nextLine(); // 输入字符串S
        String[] sArr = s.split("-"); // 将S按照“-”分隔成N+1个子串
        String prefix = sArr[0]; // 第一个子串
        StringBuilder postfixSb = new StringBuilder(); // 除第一个子串外的所有子串
        for (int i = 1; i < sArr.length; i++) {
            postfixSb.append(sArr[i]);
        }
        char[] postfixChars = postfixSb.toString().toCharArray(); // 将除第一个子串外的所有子串拼接成字符数组
        StringBuilder newSb = new StringBuilder();
        for (int i = 0; i < postfixChars.length; i++) { // 将除第一个子串外的所有子串每K个字符组成新的子串，并用‘-’分隔
            if ((i + 1) % k == 0 && i + 1 != postfixChars.length) {
                newSb.append(postfixChars[i]).append("-");
            } else {
                newSb.append(postfixChars[i]);
            }
        }
        String[] newSArr = newSb.toString().split("-"); // 将新组成的每一个子串按照“-”分隔
        StringBuilder resultSb = new StringBuilder();
        for (String str : newSArr) { // 对于新组成的每一个子串，如果它含有的小写字母比大写字母多，则将这个子串的所有大写字母转换为小写字母；反之，如果它含有的大写字母比小写字母多，则将这个子串的所有小写字母转换为大写字母；大小写字母的数量相等时，不做转换

            long upperCase = str.chars().filter(Character::isUpperCase).count();

            long lowerCase = str.chars().filter(Character::isLowerCase).count();
            if (upperCase > lowerCase) {
                resultSb.append(str.toUpperCase()).append("-");
            } else if (lowerCase > upperCase) {
                resultSb.append(str.toLowerCase()).append("-");
            } else {
                resultSb.append(str).append("-");
            }
        }
        String postfix = resultSb.toString().substring(0, resultSb.length() - 1); // 将处理后的新组成的每一个子串按照“-”拼接成字符串
        System.out.println(prefix + "-" + postfix); // 输出转换后的字符串
    }
}

import java.util.ArrayList;
import java.util.Scanner;

public class Main {
  // 字母数字类
  static class Letter {
    char letter;
    int num;

    public Letter(char letter, int num) {
      this.letter = letter;
      this.num = num;
    }

    @Override
    public String toString() {
      return this.letter + "" + this.num;
    }
  }

  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    System.out.println(getResult(sc.nextLine()));
  }

  public static String getResult(String s) {
    // 不区分大小写
    s = s.toLowerCase();

    // 统计每个字母出现的次数
    int[] count = new int[128];

    // 去除字符串中的非字母
    StringBuilder sb = new StringBuilder();

    for (int i = 0; i < s.length(); i++) {
      char c = s.charAt(i);
      if (c >= 'a' && c <= 'z') {
        count[c]++;
        sb.append(c);
      }
    }

    // 加空格是为了避免后续的收尾操作，如果有疑问可以移除下面加空格操作
    s = sb + " ";

    // 记录连续字母和非连续字母
    ArrayList<Letter> ans = new ArrayList<>();

    // 上一个位置的字母
    char pre = s.charAt(0);
    // 该字母连续次数记为1
    int repeat = 1;
    // 后续该字母还有count[pre]-=1个
    count[pre]--;

    for (int i = 1; i < s.length(); i++) {
      // 当前位置的字母
      char cur = s.charAt(i);
      // 后续该字母还有count[cur]-=1个
      count[cur]--;

      if (cur == pre) {
        // 如果当前位置和上一个位置的字母相同，则产生连续
        // 连续次数+1
        repeat++;
      } else {
        // 如果当前位置和上一个位置的字母不同，则连续打断
        // 如果pre字母连续次数>1，则是真连续，那么就是pre+repeat,否则就是假连续,是pre+count[pre]
        ans.add(new Letter(pre, repeat > 1 ? repeat : count[pre]));
        // 更新pre为cur
        pre = cur;
        // 更新pre连续次数为1
        repeat = 1;
      }
    }

    // 字母和紧随的数字作为一组进行排序，数字大的在前，数字相同的，则按字母进行排序，字母小的在前
    ans.sort((a, b) -> a.num != b.num ? b.num - a.num : a.letter - b.letter);

    StringBuilder res = new StringBuilder();
    for (Letter an : ans) {
      res.append(an.toString());
    }
    return res.toString();
  }
}

import java.util.LinkedList;
import java.util.Scanner;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    System.out.println(getResult(sc.nextLine()));
  }

  public static long getResult(String s) {
    String maxLenExp = getMaxLenExp(s);

    if (maxLenExp.length() == 0) {
      return 0;
    } else {
      return calcExpStr(maxLenExp);
    }
  }

  public static String getMaxLenExp(String s) {
    Matcher matcher = Pattern.compile("((\\d+[+*-])*\\d+)").matcher(s);

    String maxLenExp = "";

    while (matcher.find()) {
      String exp = matcher.group(0);

      if (exp.length() > maxLenExp.length()) {
        maxLenExp = exp;
      }
    }

    return maxLenExp;
  }

  public static long calcExpStr(String exp) {
    // 这里在表达式结尾追加"+0"是为了避免后面收尾操作，不理解的话，可以去掉此步，测试下"1-2"
    exp += "+0";

    // 记录表达式中各块的操作数
    LinkedList<Long> stack = new LinkedList<>();
    // 各块操作数的"值"部分的缓存容器
    StringBuilder numStr = new StringBuilder();
    // 各块操作数的"系数"部分，默认为1
    long num_coef = 1;

    for (int i = 0; i < exp.length(); i++) {
      char c = exp.charAt(i);

      if (c >= '0' && c <= '9') {
        numStr.append(c);
        continue;
      }

      // 如果扫描到的字符c是运算符，那么该运算符打断了前面操作数的扫描，前面操作数 = 系数 * 值
      long num = num_coef * Long.parseLong(numStr.toString());
      stack.add(num);

      // 清空缓存容器，用于下一个操作数的”值“记录
      numStr = new StringBuilder();

      switch (c) {
        case '+':
          // 如果运算符是加法，则后一个操作数的系数为1
          num_coef = 1;
          break;
        case '-':
          // 如果运算符是减法，则后一个操作数的系数为-1
          num_coef = -1;
          break;
        case '*':
          // 如果运算符是乘法，则后一个操作数的系数为栈顶值，比如2*3，其中2可以当作3的系数
          num_coef = stack.removeLast();
          break;
      }
    }

    // 表达式分块后，每一块独立计算，所有块的和就是表达式的结果
    long res = 0;
    for (long num : stack) {
      res += num;
    }

    return res;
  }
}

import java.util.Arrays;
import java.util.HashSet;
import java.util.LinkedList;
import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    String[] arr = sc.nextLine().split(" ");
    System.out.println(getResult(arr));
  }

  public static String getResult(String[] arr) {
    Arrays.sort(arr, (a, b) -> a.length() != b.length() ? a.length() - b.length() : a.compareTo(b));

    LinkedList<String> link = new LinkedList<>(Arrays.asList(arr));
    HashSet<String> set = new HashSet<>(link);

	String ans = "";

    while (link.size() > 0) {
      String str = link.removeLast();
      int end = str.length() - 1;

	  if(end == 0 && "".equals(ans)) {
		  ans = str;
		  continue;
	  }

      while (set.contains(str.substring(0, end))) {
        if (end == 1) {
          return str;
        } else {
          end--;
        }
      }
    }

    return ans;
  }
}

import java.util.Scanner;
import java.util.regex.Pattern;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    String[] words = sc.nextLine().split(" ");
    System.out.println(getResult(words));
  }

  public static int getResult(String[] words) {
    int count = 0;

    Pattern nonLetter = Pattern.compile("[^a-z]");
    Pattern reg1 = Pattern.compile("[^aeiou][aeiou][^aeiour]e");
    Pattern reg2 = Pattern.compile("e[^aeiour][aeiou][^aeiou]");

    for (String word : words) {
      Pattern reg = nonLetter.matcher(word).find() ? reg1 : reg2;

      for (int i = 0; i <= word.length() - 4; i++) {
        String seg = word.substring(i, i + 4);

        if (nonLetter.matcher(seg).find()) continue;

        if (reg.matcher(seg).find()) count++;
      }
    }

    return count;
  }
}

import java.util.Scanner;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // 读取源字符串和目标字符串
        String source = scanner.nextLine();
        String target = scanner.nextLine();

        // 将目标字符串中的可选段标记转换为正则表达式的可选字符
        target = target.replaceAll("\\[(.*?)\\]", "[$1]");

        // 编译目标字符串为正则表达式模式
        Pattern pattern = Pattern.compile(target);
        // 创建匹配器，用于在源字符串中查找匹配的子字符串
        Matcher matcher = pattern.matcher(source);

        // 如果找到匹配的子字符串，则输出匹配的子字符串在源字符串中的起始位置
        if (matcher.find()) {
            System.out.println(matcher.start());
        } else {
            // 如果没有找到匹配的子字符串，则输出-1
            System.out.println(-1);
        }
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int index = Integer.parseInt(scanner.nextLine()); // 输入命令字索引K
        String input = scanner.nextLine(); // 输入命令字符串S
        char[] charArray = input.toCharArray(); // 将命令字符串转换为字符数组
        String command = ""; // 当前正在解析的命令字
        List<String> commandList = new ArrayList<>(); // 存储解析后的命令字列表

        for (int i = 0; i < charArray.length; i++) {
            char ch = charArray[i];

            if (ch == '"' && command.contains(ch + "")) { // 如果当前字符为双引号且命令字中已经包含了一个双引号
                command += '"'; // 将双引号添加到命令字中
                commandList.add(command); // 将解析完毕的命令字添加到命令字列表中
                command = ""; // 重置命令字
            } else if (!command.contains("\"") && ch == '_') { // 如果命令字不包含双引号且当前字符为下划线
                if (!command.isEmpty()) { // 如果命令字不为空
                    commandList.add(command); // 将解析完毕的命令字添加到命令字列表中
                    command = ""; // 重置命令字
                }
            } else if (i == charArray.length - 1) { // 如果已经到达字符串末尾
                command += ch; // 将当前字符添加到命令字中
                commandList.add(command); // 将解析完毕的命令字添加到命令字列表中
                command = ""; // 重置命令字
            } else {
                command += ch; // 将当前字符添加到命令字中
            }
        }

        if (index < 0 || index > commandList.size() - 1) { // 如果命令字索引超出范围
            System.out.println("ERROR");
        } else {
            commandList.set(index, "******"); // 将指定索引的命令字替换为******
            StringBuilder result = new StringBuilder();

            for (String item : commandList) {
                result.append("_").append(item); // 在命令字之前添加下划线
            }

            result.deleteCharAt(0); // 删除第一个下划线
            System.out.println(result.toString());
        }
    }
}

import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s1 = scanner.nextLine();
        String s2 = scanner.nextLine();
        int k = Integer.parseInt(scanner.nextLine().trim());

        // 调用查找函数并输出结果
        System.out.println(findRedundantCover(s1, s2, k));
    }

    /**
     * 查找满足条件的子串起始位置
     * @param s1 字符串 s1
     * @param s2 字符串 s2
     * @param k  冗余长度 k
     * @return 返回满足条件的子串的最左侧起始位置，如果没有返回 -1
     */
    public static int findRedundantCover(String s1, String s2, int k) {
        // 计算 s1 中每个字符的出现次数
        int[] s1Count = new int[26];
        for (char c : s1.toCharArray()) {
            s1Count[c - 'a']++;
        }

        // 初始化滑动窗口的左右边界、剩余需要匹配的 s1 字符数和窗口内字符计数数组
        int left = 0, right = 0;
        int s1CharsLeft = s1.length();
        int[] windowCount = new int[26];

        // 遍历 s2 字符串
        while (right < s2.length()) {
            // 将右边界字符加入窗口计数
            char rightChar = s2.charAt(right);
            windowCount[rightChar - 'a']++;

            // 如果窗口中的字符在 s1 中出现过，减少剩余需要匹配的字符数
            if (windowCount[rightChar - 'a'] <= s1Count[rightChar - 'a']) {
                s1CharsLeft--;
            }

            // 如果窗口长度大于 s1 长度 + k，需要移动左边界
            if (right - left + 1 > s1.length() + k) {
                char leftChar = s2.charAt(left);
                // 如果左边界字符在 s1 中出现过，增加剩余需要匹配的字符数
                if (windowCount[leftChar - 'a'] <= s1Count[leftChar - 'a']) {
                    s1CharsLeft++;
                }
                // 将左边界字符从窗口计数中移除
                windowCount[leftChar - 'a']--;
                left++;
            }

            // 如果剩余需要匹配的字符数为0，返回满足条件的子串起始位置
            if (s1CharsLeft == 0) {
                return left;
            }

            // 移动右边界
            right++;
        }

        // 如果遍历完 s2 仍未找到满足条件的子串，返回 -1
        return -1;
    }
}

import java.util.*;

public class Main {
    static int n, m; // 分别用于存储明文的长度和密码本的尺寸
    static int[][] book; // 用于存储密码本，是一个二维数组
    static int[][] directions = {{0, 1}, {1, 0}, {-1, 0}, {0, -1}}; // 表示四个搜索方向：右、下、左、上
    static String minPath = ""; // 用于存储找到的字典序最小的密文路径
    static boolean found = false; // 标记是否找到了至少一种加密方式

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        n = scanner.nextInt(); // 读取明文的长度
        int[] data = new int[n]; // 创建数组存储明文数字
        for (int i = 0; i < n; i++) {
            data[i] = scanner.nextInt(); // 读取每个明文数字
        }

        m = scanner.nextInt(); // 读取密码本的尺寸
        book = new int[m][m]; // 初始化密码本数组
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < m; j++) {
                book[i][j] = scanner.nextInt(); // 填充密码本内容
            }
        }

        boolean[][] visited = new boolean[m][m]; // 标记密码本中的数字是否已经被访问过
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < m; j++) {
                if (book[i][j] == data[0]) { // 从找到的第一个数字开始搜索
                    dfs(data, 0, i, j, visited, ""); // 使用深度优先搜索找到所有可能的加密路径
                }
            }
        }

        System.out.println(found ? minPath.trim() : "error"); // 如果找到至少一种加密方式，输出最小字典序的密文；否则，输出"error"
    }

    public static void dfs(int[] data, int index, int x, int y, boolean[][] visited, String path) {
        if (index == n) { // 如果已经处理完所有明文数字
            if (!found || path.compareTo(minPath) < 0) { // 如果找到的是第一种加密方式，或者字典序比之前的小
                minPath = path; // 更新最小字典序密文路径
            }
            found = true; // 标记找到了加密方式
            return;
        }

        if (x < 0 || y < 0 || x >= m || y >= m || visited[x][y] || book[x][y] != data[index]) {
            // 如果坐标越界，或该位置已访问，或该位置数字与明文不匹配，则返回
            return;
        }

        visited[x][y] = true; // 标记当前位置已访问
        String newPath = path + x + " " + y + " "; // 更新路径字符串

        if (index == n - 1 || book[x][y] == data[index]) {
            dfs(data, index + 1, x, y, visited, newPath); // 继续搜索下一个明文数字
        }

        for (int[] dir : directions) { // 遍历四个方向
            int newX = x + dir[0];
            int newY = y + dir[1];
            dfs(data, index + 1, newX, newY, visited, newPath); // 在新方向上搜索下一个明文数字
        }

        visited[x][y] = false; // 回溯，撤销当前位置的访问标记
    }
}

