import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        // 创建Scanner对象用于获取用户输入
        Scanner scanner = new Scanner(System.in);
        // 使用StringBuilder来构建整个输入文本
        StringBuilder input = new StringBuilder();
        // 循环读取每一行输入直到没有新的输入
        while (scanner.hasNextLine()) {
            // 将读取的每一行追加到StringBuilder对象，并添加换行符
            input.append(scanner.nextLine()).append("\n");
        }
        // 关闭Scanner对象
        scanner.close();
        // 输出文本统计结果
        System.out.println(countTexts(input.toString()));
    }

    // 统计文本中的文本数量
    private static int countTexts(String input) {
        // 初始化计数器
        int count = 0;
        // 标记是否在字符串内部
        boolean inString = false;
        // 标记是否在注释内部
        boolean inComment = false;
        // 记录字符串分隔符
        char stringDelimiter = 0;
        // 标记当前是否为空文本（即没有遇到非空白字符）
        boolean isEmpty = true;

        // 遍历输入文本的每个字符
        for (int i = 0; i < input.length(); i++) {
            // 当前字符
            char c = input.charAt(i);
            // 下一个字符（如果存在）
            char nextChar = (i + 1 < input.length()) ? input.charAt(i + 1) : '\0';

            // 如果在注释中
            if (inComment) {
                // 如果遇到换行符，则注释结束
                if (c == '\n') {
                    inComment = false;
                }
                continue;
            }

            // 如果遇到连续的两个减号，并且不在字符串内，则进入注释状态
            if (c == '-' && nextChar == '-' && !inString) {
                inComment = true;
                continue;
            }

            // 如果遇到单引号或双引号，并且不在字符串内，则进入字符串状态
            if ((c == '\'' || c == '\"') && !inString) {
                inString = true;
                stringDelimiter = c;
                isEmpty = false;
                continue;
            }

            // 如果在字符串内，并且遇到了相同的分隔符，则检查是否为转义
            if (c == stringDelimiter && inString) {
                if (nextChar == stringDelimiter) {
                    i++; // 跳过转义的引号
                } else {
                    inString = false; // 字符串结束
                }
                continue;
            }

            // 如果遇到分号，并且不在字符串内，则增加计数器
            if (c == ';' && !inString) {
                if (!isEmpty) {
                    count++;
                    isEmpty = true;
                }
                continue;
            }

            // 如果遇到非空白字符，并且不在字符串内，则标记为非空文本
            if (!Character.isWhitespace(c) && !inString) {
                isEmpty = false;
            }
        }

        // 如果最后一个文本没有闭合的分号，则增加计数器
        if (!isEmpty) {
            count++; // 最后一个文本没有闭合分号
        }

        return count;
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        String str1 = sc.next();
        String str2 = sc.next();

        System.out.println(getResult(str1, str2));
    }

    public static String getResult(String str1, String str2) {
        String reg = "[0-9a-f]+";

        String[] valids = str1.split(reg);

        int count = getDistinctCount(str2);

        String[] ans = Arrays.stream(valids).filter(valid -> !"".equals(valid) && getDistinctCount(valid) <= count).toArray(String[]::new);

        if(ans.length == 0) return "Not Found";

        Arrays.sort(ans, (a,b)->{
            int c1 = getDistinctCount(a);
            int c2 = getDistinctCount(b);
            return c1 != c2 ? c2 - c1 : b.compareTo(a);
        });

        return ans[0];
    }

    public static int getDistinctCount(String str) {
        HashSet<Character> set = new HashSet<>();
        for (char c : str.toCharArray()) {
            set.add(c);
        }
        return set.size();
    }
}

import java.util.LinkedList;
import java.util.Scanner;

public class Main {
  static class ZipStr {
    int num;
    char c;

    public ZipStr(int num, char c) {
      this.num = num;
      this.c = c;
    }
  }

  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    String s1 = sc.nextLine();
    String s2 = sc.nextLine();

    System.out.println(getResult(s1, s2));
  }

  public static String getResult(String s1, String s2) {
    LinkedList<ZipStr> link1 = getZipStrLink(s1);
    LinkedList<ZipStr> link2 = getZipStrLink(s2);

    int diff = 0;
    int same = 0;

    while (link1.size() > 0) {
      ZipStr zipStr1 = link1.removeFirst();
      ZipStr zipStr2 = link2.removeFirst();

      int compareCount = Math.min(zipStr1.num, zipStr2.num);

      if (zipStr1.c != zipStr2.c) {
        diff += compareCount;
      } else {
        same += compareCount;
      }

      if (zipStr1.num > compareCount) {
        zipStr1.num -= compareCount;
        link1.addFirst(zipStr1);
        continue;
      }

      if (zipStr2.num > compareCount) {
        zipStr2.num -= compareCount;
        link2.addFirst(zipStr2);
      }
    }

    return diff + "/" + (diff + same);
  }

  public static LinkedList<ZipStr> getZipStrLink(String s) {
    LinkedList<ZipStr> link = new LinkedList<>();

    StringBuilder num = new StringBuilder();

    for (int i = 0; i < s.length(); i++) {
      char c = s.charAt(i);

      if (c >= '0' && c <= '9') {
        num.append(c);
      } else {
        link.add(new ZipStr(Integer.parseInt(num.toString()), c));
        num = new StringBuilder();
      }
    }

    return link;
  }
}

import java.util.HashSet;
import java.util.Scanner;

public class Main {
    static String[] map = {"abc", "def", "ghi", "jkl", "mno", "pqr", "st", "uv", "wx", "yz"};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // 输入数字字符串
        char[] digits = sc.next().toCharArray();
        // 输入屏蔽字符串
        String filter = sc.next();

        // 根据数字字符串得到每个数字对应的字母字符串
        String[] letters = new String[digits.length];
        for (int i = 0; i < digits.length; i++) {
            letters[i] = map[digits[i] - '0'];
        }

        // 用于存储结果的字符串
        StringBuilder sb = new StringBuilder();
        // 开始进行深度优先搜索
        dfs(letters, 0, new StringBuilder(), sb, filter, new HashSet<>());

        // 输出结果
        System.out.println(sb.toString());
    }

    public static void dfs(
            String[] letters, int index, StringBuilder path, StringBuilder res, String filter, HashSet<Character> used) {
        if (index == letters.length) {
            // 过滤包含屏蔽字符串的路径
            if (!path.toString().contains(filter)) {
                res.append(path).append(",");
            }
            return;
        }

        // 对于每个数字，遍历其对应的字母字符串
        for (int i = 0; i < letters[index].length(); i++) {
            char c = letters[index].charAt(i);
            if (!used.contains(c)) {
                path.append(c);
                used.add(c);
                dfs(letters, index + 1, path, res, filter, used);
                path.deleteCharAt(path.length() - 1);
                used.remove(c);
            }
        }
    }
}

import java.util.ArrayList;
import java.util.Scanner;

public class Main {
    // 定义App类，用于存储App的相关信息
    static class App {
        String name; // App名称
        int priority; // App优先级
        int startTime; // App允许使用的起始时间（以分钟为单位）
        int endTime; // App允许使用的结束时间（以分钟为单位）

        // App类的构造函数，用于创建App对象
        public App(String name, int priority, int startTime, int endTime) {
            this.name = name;
            this.priority = priority;
            this.startTime = startTime;
            this.endTime = endTime;
        }
    }

    // 主函数
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in); // 创建Scanner对象，用于读取标准输入
        int n = sc.nextInt(); // 读取App数量

        ArrayList<App> apps = new ArrayList<>(); // 创建App列表，用于存储所有App
        for (int i = 0; i < n; i++) {
            // 循环读取每个App的信息，并创建App对象添加到列表中
            String appName = sc.next();
            int appPriority = sc.nextInt();
            int appStartTime = convertTime(sc.next());
            int appEndTime = convertTime(sc.next());
            apps.add(new App(appName, appPriority, appStartTime, appEndTime));
        }

        int queryTime = convertTime(sc.next()); // 读取查询时间，并转换为分钟
        String appAtTime = "NA"; // 初始化查询时间对应的App名称为"NA"

        // 创建已注册App列表
        ArrayList<App> registeredApps = new ArrayList<>();
        for (App app : apps) {
            if (app.startTime >= app.endTime) continue; // 如果起始时间不小于结束时间，则跳过

            // 遍历已注册的App列表，检查时间冲突
            for (int i = registeredApps.size() - 1; i >= 0; i--) {
                App registered = registeredApps.get(i);
                // 如果存在时间冲突
                if (Math.max(app.startTime, registered.startTime) < Math.min(app.endTime, registered.endTime)) {
                    // 如果当前App的优先级高于已注册App的优先级
                    if (app.priority > registered.priority) {
                        registeredApps.remove(i); // 注销低优先级的App
                    } else {
                        continue; // 如果优先级不高，继续检查下一个已注册App
                    }
                }
            }

            // 将当前App添加到已注册App列表中
            registeredApps.add(app);
        }

        // 遍历已注册App列表，找到查询时间对应的App
        for (App app : registeredApps) {
            if (queryTime >= app.startTime && queryTime < app.endTime) {
                appAtTime = app.name; // 更新查询时间对应的App名称
                break; // 找到后退出循环
            }
        }

        System.out.println(appAtTime); // 输出查询时间对应的App名称
    }

    // 时间转换函数，将时间字符串转换为以分钟为单位的整数
    private static int convertTime(String time) {
        String[] parts = time.split(":"); // 将时间字符串按照":"分割
        return Integer.parseInt(parts[0]) * 60 + Integer.parseInt(parts[1]); // 将小时和分钟转换为分钟
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        // 创建Scanner对象读取输入
        Scanner scanner = new Scanner(System.in);
        // 读取测试用例数量
        int testCases = Integer.parseInt(scanner.nextLine().trim());
        // 使用StringBuilder来构建所有测试用例的输出结果
        StringBuilder results = new StringBuilder();
        // 遍历处理每个测试用例
        while (testCases-- > 0) {
            // 读取并分割每个测试用例的考勤记录
            String[] attendanceRecords = scanner.nextLine().trim().split(" ");
            // 判断是否能获得考勤奖，并追加结果到results
            results.append(canReceiveAward(attendanceRecords) ? "true" : "false");
            // 如果还有剩余测试用例，追加一个空格分隔
            if (testCases > 0) {
                results.append(" ");
            }
        }
        // 输出所有测试用例的结果
        System.out.println(results.toString());
        // 关闭Scanner
        scanner.close();
    }

    // 判断是否能获得考勤奖的方法
    private static boolean canReceiveAward(String[] records) {
        // 缺勤次数计数器
        int absentCount = 0;
        // 遍历考勤记录
        for (int i = 0; i < records.length; i++) {
            // 如果记录为缺勤，增加缺勤计数
            if ("absent".equals(records[i])) {
                absentCount++;
                // 如果缺勤超过1次，返回false
                if (absentCount > 1) return false;
            }
            // 如果记录为迟到或早退，且前一天也是迟到或早退，返回false
            if ("late".equals(records[i]) || "leaveearly".equals(records[i])) {
                if (i > 0 && ("late".equals(records[i - 1]) || "leaveearly".equals(records[i - 1]))) {
                    return false;
                }
            }
            // 检查任意连续7天的考勤记录
            if (i >= 6) {
                int countIn7Days = 0;
                // 计算连续7天内非正常上班的天数
                for (int j = i - 6; j <= i; j++) {
                    if (!"present".equals(records[j])) {
                        countIn7Days++;
                    }
                }
                // 如果连续7天内非正常上班超过3天，返回false
                if (countIn7Days > 3) return false;
            }
        }
        // 如果所有条件都满足，返回true
        return true;
    }
}

import java.util.Arrays;
import java.util.Scanner;
import java.util.StringJoiner;

public class Main {
    public static void main(String[] args) {
        // 创建Scanner对象用于获取用户输入
        Scanner sc = new Scanner(System.in);
        // 读取一行输入并将其分割为字符串数组，然后转换为整数数组
        int[] tmp = Arrays.stream(sc.nextLine().split(" ")).mapToInt(Integer::parseInt).toArray();
        // 获取投资项目数量m、总投资额N和风险容忍度X
        int m = tmp[0];
        int N = tmp[1];
        int X = tmp[2];
        // 读取每个项目的预期回报率
        int[] returns = Arrays.stream(sc.nextLine().split(" ")).mapToInt(Integer::parseInt).toArray();
        // 读取每个项目的风险值
        int[] risks = Arrays.stream(sc.nextLine().split(" ")).mapToInt(Integer::parseInt).toArray();
        // 读取每个项目的最大投资额
        int[] maxInvestments = Arrays.stream(sc.nextLine().split(" ")).mapToInt(Integer::parseInt).toArray();

        // 初始化最大回报为0
        int maxReturn = 0;
        // 初始化最大回报对应的投资方案数组
        int[] bestInvestments = new int[m];

        // 遍历所有项目
        for (int i = 0; i < m; i++) {
            // 如果单个项目的风险在容忍度范围内
            if (risks[i] <= X) {
                // 计算对项目i的投资额，不超过总投资额N和项目i的最大投资额
                int investmentForI = Math.min(N, maxInvestments[i]);
                // 计算当前回报
                int currentReturn = investmentForI * returns[i];
                // 如果当前回报大于已知的最大回报
                if (currentReturn > maxReturn) {
                    // 更新最大回报
                    maxReturn = currentReturn;
                    // 重置最佳投资方案数组，并为项目i分配投资额
                    bestInvestments = new int[m];
                    bestInvestments[i] = investmentForI;
                }
            }

            // 遍历项目i之后的项目，寻找两个项目的组合投资方案
            for (int j = i + 1; j < m; j++) {
                // 如果两个项目的风险总和在容忍度范围内
                if (risks[i] + risks[j] <= X) {
                    int investmentForI, investmentForJ;
                    // 根据预期回报率决定投资额分配
                    if (returns[i] > returns[j]) {
                        // 如果项目i的回报率高于项目j，优先投资项目i
                        investmentForI = Math.min(N, maxInvestments[i]);
                        investmentForJ = Math.min(N - investmentForI, maxInvestments[j]);
                    } else {
                        // 如果项目j的回报率高于项目i，优先投资项目j
                        investmentForJ = Math.min(N, maxInvestments[j]);
                        investmentForI = Math.min(N - investmentForJ, maxInvestments[i]);
                    }
                    // 计算当前两个项目组合的回报
                    int currentReturn = investmentForI * returns[i] + investmentForJ * returns[j];
                    // 如果当前回报大于已知的最大回报
                    if (currentReturn > maxReturn) {
                        // 更新最大回报
                        maxReturn = currentReturn;
                        // 重置最佳投资方案数组，并为两个项目分配投资额
                        bestInvestments = new int[m];
                        bestInvestments[i] = investmentForI;
                        bestInvestments[j] = investmentForJ;
                    }
                }
            }
        }

        // 创建StringJoiner对象，用于构建输出格式
        StringJoiner sj = new StringJoiner(" ");
        // 遍历最佳投资方案数组，将投资额添加到StringJoiner中
        for (int investment : bestInvestments) {
            sj.add(String.valueOf(investment));
        }

        // 输出最佳投资方案
        System.out.println(sj.toString());
        // 关闭Scanner对象
        sc.close();
    }
}

import java.util.*;
import java.util.stream.Collectors;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    // 期望的楼层, 序列总个数
    int m = sc.nextInt(), n = sc.nextInt();

    // 序列
    Integer[] nums = new Integer[n];
    for (int i = 0; i < n; i++) nums[i] = sc.nextInt();

    System.out.println(getResult(m, n, nums));
  }

  static int expectUpCount; // 上升序列组合的元素个数
  static int limitUpSum; // 上升序列组合的元素之和的上限
  static int maxUpSumBelowLimit = 0; // 记录不超过limitUpSum的最大的上升序列的和，该变量用于帮助ans剔除不是最优解的上升序列
  static ArrayList<boolean[]> paths = new ArrayList<>(); // paths记录求组合过程中发现的符合要求的序列

  public static String getResult(int m, int n, Integer[] nums) {
    // 计算expectUpCount、limitUpSum
    int sum = Arrays.stream(nums).reduce(Integer::sum).orElse(0);
    expectUpCount = n / 2 + n % 2;
    limitUpSum = (sum + m) / 2;

    // 将原始序列降序
    Arrays.sort(nums, (a, b) -> b - a);

    // 求组合
    dfs(nums, 0, new boolean[n], 0, 0);

    // 本题没有说明异常处理，我理解应该不会存在paths.size == 0的情况，但是为了保险，还是处理一下
    if (paths.size() == 0) {
      return "-1";
    }

    // 首先将paths转化为结果序列，然后对结果序列进行排序，排序规则是：按先处理大值的原则, 最后取出最优解
    ArrayList<Integer> ans =
      paths.stream()
        .map(path -> getSeq(path, nums))
        .sorted((seq1, seq2) -> compare(seq1, seq2))
        .collect(Collectors.toList())
        .get(0);

    // 打印最优序列
    StringJoiner sj = new StringJoiner(" ");
    for (Integer v : ans) sj.add(v + "");
    return sj.toString();
  }

  /**
   * 该方法用于选取出上升序列的组合
   *
   * @param nums 原始序列（降序排序后）
   * @param index 当前层级能选取的元素范围的起始索引
   * @param path
   *     记录上升序列组合，注意path这里采用的是nums.length长度的boolean[]数组，如果path[i]为true，则代表nums[i]是上升，否则nums[i]就是下降
   * @param sum 上升序列组合的元素和
   * @param count 上升序列组合的元素个数
   */
  public static void dfs(Integer[] nums, int index, boolean[] path, int sum, int count) {
    // 如果上升序列元素个数超过了expectUpCount, 则结束对应递归
    if (count > expectUpCount) return;

    if (count == expectUpCount) {
      // 非更优解，直接剔除
      if (sum < maxUpSumBelowLimit) return;

      // 发现更优解，则清空paths
      if (sum > maxUpSumBelowLimit) {
        maxUpSumBelowLimit = sum;
        paths.clear();
      }

      // 记录对应解
      paths.add(Arrays.copyOf(path, path.length));
      return;
    }

    for (int i = index; i < nums.length; i++) {
      int num = nums[i];

      if (sum + num > limitUpSum) continue;

      path[i] = true;
      dfs(nums, i + 1, path, sum + num, count + 1);
      path[i] = false;
    }
  }

  // 根据path解析出上升序列和下降序列，并对上升序列和下降序列进行交叉合并，形成目标序列
  public static ArrayList<Integer> getSeq(boolean[] path, Integer[] nums) {
    // 上升序列
    LinkedList<Integer> up = new LinkedList<>();
    // 下降序列
    LinkedList<Integer> down = new LinkedList<>();

    // 根据path解析出上升序列、下降序列
    for (int i = 0; i < nums.length; i++) {
      if (path[i]) up.add(nums[i]);
      else down.add(nums[i]);
    }

    // 目标序列容器
    ArrayList<Integer> seq = new ArrayList<>();

    // 交叉合并
    for (int i = 0; i < nums.length / 2; i++) {
      seq.add(up.removeFirst());
      seq.add(down.removeFirst());
    }

    if (up.size() > 0) {
      seq.add(up.removeFirst());
    }

    return seq;
  }

  // 比较相同长度的两个集合的大小, 按逐个元素比较
  public static int compare(ArrayList<Integer> list1, ArrayList<Integer> list2) {
    for (int i = 0; i < list1.size(); i++) {
      int v1 = list1.get(i);
      int v2 = list2.get(i);

      if (v1 > v2) return -1;
      if (v1 < v2) return 1;
    }
    return 0;
  }
}

import java.util.HashMap;
import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    System.out.println(getResult(sc.next()));
  }

  public static int getResult(String str) {
    // count用于记录W,A,S,D字母的数量
    HashMap<Character, Integer> count = new HashMap<>();

    for (int i = 0; i < str.length(); i++) {
      Character c = str.charAt(i);
      count.put(c, count.getOrDefault(c, 0) + 1);
    }

    // 平衡状态时，W,A,S,D应该都是avg数量
    int avg = str.length() / 4;

    // total用于记录多余字母个数
    int total = 0;

    // flag表示当前是否为平衡状态，默认是
    boolean flag = true;

    for (Character c : count.keySet()) {
      if (count.get(c) > avg) {
        // 如果有一个字母数量超标，则平衡打破
        flag = false;
        // 此时count记录每个字母超过avg的数量
        count.put(c, count.get(c) - avg);
        total += count.get(c);
      } else {
        count.put(c, 0); // 此时count统计的其实是多余字母，如果没有超过avg,则表示没有多余字母
      }
    }

    // 如果平衡，则输出0
    if (flag) return 0;

    int i = 0;
    int j = 0;
    int minLen = str.length() + 1;

    while (j < str.length()) {
      Character jc = str.charAt(j);

      if (count.get(jc) > 0) {
        total--;
      }
      count.put(jc, count.get(jc) - 1);

      while (total == 0) {
        minLen = Math.min(minLen, j - i + 1);

        Character ic = str.charAt(i);
        if (count.get(ic) >= 0) {
          total++;
        }
        count.put(ic, count.get(ic) + 1);

        i++;
      }
      j++;
    }
    return minLen;
  }
}

analysis:
题目要求，保持W,A,S,D字母个数平衡，即相等，如果不相等，可以从字符串中选取一段连续子串替换，来让字符串平衡。
比如：WWWWAAAASSSS
字符串长度12，W,A,S,D平衡的话，则每个字母个数应该是3个，而现在W,A,S各有4个，也就是说各超了1个。
因此我们应该从字符串中，选取一段包含1个W，1个A，1个S的子串，来替换为D。
WWWWAAAASSSS
WWWWAAAASSSS
WWWWAAAASSSS
........
WWWWAAAASSSS
而符合这种要求的子串可能很多，我们需要找出其中最短的，即WAAAAS。
本题其实就是求最小覆盖子串，同LeetCode - 76JavaScript算法源码/* JavaScript Node ACM模式 控制台输入获取 */
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

rl.on("line", (line) => {
  console.log(getResult(line));
});

function getResult(str) {
  // 此时count记录统计W,A,S,D字母的数量
  const count = {
    W: 0,
    A: 0,
    S: 0,
    D: 0,
  };

  for (let c of str) count[c]++;

  // 平衡状态时，W,A,S,D应该都是avg数量
  const avg = str.length / 4;

  let total = 0; // total用于记录多余字母个数

  let flag = true; // flag表示当前是否为平衡状态，默认是
  for (let c in count) {
    if (count[c] > avg) {
      flag = false; // 如果有一个字母数量超标，则平衡打破
      count[c] -= avg; // 此时count记录每个字母超过avg的数量
      total += count[c];
    } else {
      delete count[c];
    }
  }

  if (flag) return 0; // 如果平衡，则输出0

  let i = 0;
  let j = 0;
  let minLen = str.length + 1;

  while (j < str.length) {
    const jc = str[j];

    if (count[jc]-- > 0) {
      total--;
    }

    while (total === 0) {
      minLen = Math.min(minLen, j - i + 1);

      const ic = str[i];
      if (count[ic]++ >= 0) {
        total++;
