        if (len1 == 2 || len2 == 2) {
          if (len1 == 2) dfs(link1, 0, 2, new ArrayList<>(), ans);
          if (len2 == 2) dfs(link2, 0, 2, new ArrayList<>(), ans);
        } else if (len1 == 4 || len2 == 4) {
          if (len1 == 4) dfs(link1, 0, 2, new ArrayList<>(), ans);
          if (len2 == 4) dfs(link2, 0, 2, new ArrayList<>(), ans);
        } else if (len1 == 3 || len2 == 3) {
          if (len1 == 3) dfs(link1, 0, 2, new ArrayList<>(), ans);
          if (len2 == 3) dfs(link2, 0, 2, new ArrayList<>(), ans);
        }
        break;
      case "4":
        if (len1 == 4 || len2 == 4) {
          if (len1 == 4) ans.add(link1);
          if (len2 == 4) ans.add(link2);
        }
        break;
      case "8":
        if (len1 == 4 && len2 == 4) {
          ans.add(
              Stream.concat(link1.stream(), link2.stream())
                  .collect(Collectors.toCollection(ArrayList<Integer>::new)));
        }
        break;
    }

    return ans.toString();
  }

  public static void dfs(
      ArrayList<Integer> arr,
      int index,
      int level,
      ArrayList<Integer> path,
      ArrayList<ArrayList<Integer>> res) {
    if (path.size() == level) {
      res.add(new ArrayList<>(path));
      return;
    }

    for (int i = index; i < arr.size(); i++) {
      path.add(arr.get(i));
      dfs(arr, i + 1, level, path, res);
      path.remove(path.size() - 1);
    }
  }
}

import java.util.*;

public class Main {
    // 定义常量，表示汽车油箱的最大容量
    private static final int MAX_FUEL = 100; 

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in).useDelimiter(",|\\s+");
        // 读取地图的行数和列数
        int numRows = scanner.nextInt();
        int numCols = scanner.nextInt();
        // 创建地图数组
        int[][] map = new int[numRows][numCols];

        // 填充地图数组，读取每个单元的值
        for (int i = 0; i < numRows; i++) {
            for (int j = 0; j < numCols; j++) {
                map[i][j] = scanner.nextInt();
            }
        }

        // 计算并获取最小初始油量
        int minFuel = findMinimumInitialFuel(map, numRows, numCols);
        // 输出计算结果
        System.out.println(minFuel);
    }

    // 使用二分查找方法确定从起点到终点所需的最小初始油量
    private static int findMinimumInitialFuel(int[][] map, int numRows, int numCols) {
        int low = 0, high = MAX_FUEL, optimalFuel = -1; // 初始化二分查找的上下界及结果

        while (low <= high) {
            int mid = (low + high) / 2;
            // 判断当前中值油量是否足以到达终点
            if (canReachDestination(map, mid, numRows, numCols)) {
                optimalFuel = mid; // 更新找到的可行油量
                high = mid - 1; // 尝试寻找更小的可行油量
            } else {
                low = mid + 1; // 增加油量尝试
            }
        }
        return optimalFuel; // 返回最小初始油量，如果无法到达则返回-1
    }

    // 检查给定起始油量是否足以从起点到达终点
    private static boolean canReachDestination(int[][] map, int startFuel, int numRows, int numCols) {
        if (map[0][0] == 0) return false; // 起点如果是障碍物，则无法出发

        // 初始化每个位置的剩余油量数组
        int[][] remainingFuel = new int[numRows][numCols];
        for (int[] row : remainingFuel) {
            Arrays.fill(row, -1);
        }
        // 设置起点的初始油量
        remainingFuel[0][0] = map[0][0] == -1 ? MAX_FUEL : startFuel - map[0][0];
        if (remainingFuel[0][0] < 0) return false; // 如果起始油量不足以离开起点，返回false

        // 使用优先队列按照油量从大到小进行搜索
        PriorityQueue<int[]> priorityQueue = new PriorityQueue<>((a, b) -> b[2] - a[2]);
        priorityQueue.offer(new int[]{0, 0, remainingFuel[0][0]});
        int[] dx = {0, 1, 0, -1}; // 搜索方向数组x
        int[] dy = {1, 0, -1, 0}; // 搜索方向数组y

        // BFS搜索
        while (!priorityQueue.isEmpty()) {
            int[] current = priorityQueue.poll();
            int currentRow = current[0], currentCol = current[1], fuel = current[2];

            if (currentRow == numRows - 1 && currentCol == numCols - 1) return true; // 如果到达终点，则返回true

            // 检查四个方向
            for (int direction = 0; direction < 4; direction++) {
                int newRow = currentRow + dx[direction], newCol = currentCol + dy[direction];
                if (isValid(newRow, newCol, numRows, numCols, map)) { // 检查新位置是否有效
                    int newFuel = map[newRow][newCol] == -1 ? MAX_FUEL : fuel - map[newRow][newCol];
                    if (newFuel > remainingFuel[newRow][newCol]) {
                        remainingFuel[newRow][newCol] = newFuel;
                        priorityQueue.offer(new int[]{newRow, newCol, newFuel});
                    }
                }
            }
        }
        return false; // 如果无法到达终点，则返回false
    }

    // 判断指定位置是否有效（不越界，非障碍物）
    private static boolean isValid(int row, int col, int numRows, int numCols, int[][] map) {
        return row >= 0 && row < numRows && col >= 0 && col < numCols && map[row][col] != 0;
    }
}

import java.util.Scanner;

public class Main {
  static long x;
  static long y;
  static long cntx;
  static long cnty;

  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    x = sc.nextInt();
    y = sc.nextInt();
    cntx = sc.nextInt();
    cnty = sc.nextInt();

    long min = cntx + cnty;
    //    long max = Long.MAX_VALUE;  // 使用此上限，实际通过率55%
    long max = 1000000000L; // 使用此上限，实际通过率可以100%

    while (min <= max) {
      long mid = min + (max - min) / 2;

      if (check(mid)) {
        max = mid - 1;
      } else {
        min = mid + 1;
      }
    }

    System.out.println(min);
  }

  public static boolean check(long k) {
    long A = k / x; // 1~k范围内x倍数的数量
    long B = k / y; // 1~k范围内y倍数的数量
    long C = k / (x * y); // 1~k范围内x*y倍数的数量

    return Math.max(0, cntx - (B - C)) + Math.max(0, cnty - (A - C)) <= k - A - B + C;
  }
}

import java.util.Arrays;
import java.util.Scanner;
import java.util.StringJoiner;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    int sum = sc.nextInt();
    int n = sc.nextInt();

    Integer[] arr = new Integer[n];
    for (int i = 0; i < n; i++) {
      arr[i] = sc.nextInt();
    }

    System.out.println(getResult(sum, arr, n));
  }

  public static String getResult(int sum, Integer[] arr, int n) {
    long total = 0;
    int max_maxCapacity = 0;
    for (int i = 0; i < n; i++) {
      max_maxCapacity = Math.max(max_maxCapacity, arr[i]);
      total += arr[i];
    }

    if (total <= sum) return "[]";

    int min_maxCapacity = sum / n;

    final int min_maxCapacity_copy = min_maxCapacity;
    Integer[] ans =
        Arrays.stream(arr)
            .map(count -> count > min_maxCapacity_copy ? count - min_maxCapacity_copy : 0)
            .toArray(Integer[]::new);

    while (max_maxCapacity - min_maxCapacity > 1) {
      int maxCapacity = (max_maxCapacity + min_maxCapacity) / 2;

      // tmp数组保存的是每个桶移除的球的数量
      Integer[] tmp = new Integer[n];
      long remain = total;
      for (int i = 0; i < arr.length; i++) {
        // r是每个桶需要移除的球的个数，如果桶内球数超过maxCapacity，则需要移除超出部分，否则不需要移除
        int r = arr[i] > maxCapacity ? arr[i] - maxCapacity : 0;
        remain -= r;
        tmp[i] = r;
      }

      if (remain > sum) {
        max_maxCapacity = maxCapacity;
      } else if (remain < sum) {
        min_maxCapacity = maxCapacity;
        ans = tmp;
      } else {
        ans = tmp;
        break;
      }
    }

    StringJoiner sj = new StringJoiner(",", "[", "]");
    for (Integer an : ans) {
      sj.add(an + "");
    }

    return sj.toString();
  }
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {
  static int[] a;
  static int[] b;

  static int maxBiggerCount = 0;
  static int ans = 0;

  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    a = Arrays.stream(sc.nextLine().split(" ")).mapToInt(Integer::parseInt).toArray();
    b = Arrays.stream(sc.nextLine().split(" ")).mapToInt(Integer::parseInt).toArray();

    // 求解a的全排列
    dfs(0, new boolean[a.length], 0);

    System.out.println(ans);
  }

  public static void dfs(int level, boolean[] used, int biggerCount) {
    if (level >= a.length) {
      if (biggerCount > maxBiggerCount) {
        maxBiggerCount = biggerCount;
        ans = 1;
      } else if (biggerCount == maxBiggerCount) {
        ans++;
      }

      return;
    }

    for (int i = 0; i < a.length; i++) {
      if (used[i]) continue;

      used[i] = true;
      // biggerCount记录当前全排列中a[level] > b[level]的位置的数量, 此时a[level] == a[i]
      dfs(level + 1, used, biggerCount + (a[i] > b[level] ? 1 : 0));
      used[i] = false;
    }
  }
}

import java.util.Arrays;
import java.util.LinkedList;
import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    int[] inputs = Arrays.stream(sc.nextLine().split(",")).mapToInt(Integer::parseInt).toArray();
    int[] outputs = Arrays.stream(sc.nextLine().split(",")).mapToInt(Integer::parseInt).toArray();

    // 利用队列结构模拟圆桶
    LinkedList<Integer> queue = new LinkedList<>();

    // outputs[index]是要被取出的篮球的编号
    int index = 0;

    // 记录题解
    StringBuilder sb = new StringBuilder();

    for (int input : inputs) {
      // 按照放入顺序，从圆桶右边放入
      queue.addLast(input);

      // 然后开始尝试取出
      while (queue.size() > 0) {
        // 圆桶左边的篮球的编号
        int left = queue.getFirst();
        // 圆桶右边的篮球的编号
        int right = queue.getLast();

        if (left == outputs[index]) {
          // 优先比较圆桶左边的篮球是不是当前要取出的篮球，优先左边的原因是：当桶只有一个篮球的情况下，必须从左边取出
          sb.append("L");
          queue.removeFirst();
          index++;
        } else if (right == outputs[index]) {
          // 比较圆桶右边的篮球是不是当前要取出的篮球
          sb.append("R");
          queue.removeLast();
          index++;
        } else {
          // 如果圆桶左右两边都不是要取出的球，则本轮取出流程结束
          break;
        }
      }
    }

    // 最终如果圆桶空了，则说明所有球都取出了，否则按照给定要求无法取出所有球
    if (queue.size() != 0) {
      System.out.println("NO");
    } else {
      System.out.println(sb);
    }
  }
}

import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
  static int t;
  static int n;
  static int roadCost;
  static int[][] mds;

  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    t = sc.nextInt();
    n = sc.nextInt();

    // roadCost是A~B城市必需的路程时间
    roadCost = 0;
    for (int i = 0; i < n + 1; i++) {
      roadCost += sc.nextInt();
    }

    mds = new int[n][2];
    for (int i = 0; i < n; i++) {
      mds[i][0] = sc.nextInt();
      mds[i][1] = sc.nextInt();
    }

    System.out.println(getResult());
  }

  public static int getResult() {
    // remain是刨去必要的路程时间后，剩余可以用于赚钱的时间
    int remain = t - roadCost;

    // 如果没有剩余时间可以用，则赚不到钱
    if (remain <= 0) {
      return 0;
    }

    // 优先队列（小顶堆）记录赚到的钱, 即堆顶是某天赚的最少的钱
    PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> a - b);

    for (int[] md : mds) {
      // 第一天卖唱可以赚m，后续每天的收入会减少d
      int m = md[0];
      int d = md[1];

      // 只要在当前城市还有钱赚，那么就继续待
      while (m > 0) {
        // 只有remain天可以赚钱，超出的时间不能赚钱，因此需要比较超出的时间赚的钱m，和前面时间中赚的最少的钱pq.peek
        if (pq.size() >= remain) {
          // pq.peek只可能是某座城市停留的最后一天的赚的钱，因为每座城市都是停留的最后一天赚的钱最少
          if (m > pq.peek()) {
            // 如果当前城市当天赚的钱m，比前面天里面赚的最少的pq.peek多，那么就赚pq.peek钱的那天时间节约下来，给当天用
            pq.poll();
          } else {
            // 如果当前城市当天赚的钱m，比前面天里面赚的最少的pq.peek还少，则当前城市继续待下去赚的钱只会更少，因此没必要呆下去了
            break;
          }
        }

        // 如果所有城市停留时间没有超出remain天，或者当天是超出的时间，但是比前面赚的最少的一天的赚的更多，则赚m更优
        pq.add(m);

        //  每天收入减少d
        m -= d;
      }
    }

    return pq.stream().reduce(Integer::sum).orElse(0);
  }
}

const rl = require("readline").createInterface({ input: process.stdin });
var iter = rl[Symbol.asyncIterator]();
const readline = async () => (await iter.next()).value;

void (async function () {
    // Write your code here
    const m = (await readline()) - 0; // 获取总任务数m
    const tasks = [];

    // 循环m次,每次获取一个任务下的机器详情
    for (let i = 0; i < m; i++) {
        const n = (await readline()) - 0; //获取机器数n
        const machines = [];

        //循环n次，每次获取一个机器的 配置时间、运行时间
        for (let j = 0; j < n; j++) {
            const machine = await readline(); // 获取机器的 配置时间、运行时间
            machines.push(machine.split(" ").map(Number));
        }

        // tasks中存放的是task，每个task下又存放多个机器信息，每个机器信息包括：配置时间、运行时间
        tasks.push(machines);
    }

    // 业务逻辑
    for (let task of tasks) {
        // 将每个任务中的机器工作顺序，按照运行时间降序排序
        task.sort((a, b) => b[1] - a[1]);

        let config_endTime = 0;
        let ans = 0;

        for (let [config_cost, run_cost] of task) {
            config_endTime += config_cost;
            ans = Math.max(ans, config_endTime + run_cost);
        }

        console.log(ans);
    }
})();

import java.util.*;
import java.util.regex.*;

public class Main {

    /* 将时间字符串转换为毫秒数 */
public static int convertToMillisecond(String timeStr) {
    Pattern pattern = Pattern.compile("(\\d+):(\\d+):(\\d+).(\\d+)");
    Matcher matcher = pattern.matcher(timeStr);
    return matcher.find() ? ((Integer.parseInt(matcher.group(1)) * 60 + Integer.parseInt(matcher.group(2))) * 60 + Integer.parseInt(matcher.group(3))) * 1000 + Integer.parseInt(matcher.group(4)) : 0;
}

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        List<String> logs = new ArrayList<>();
        int n = scanner.nextInt();
        scanner.nextLine(); // 忽略换行符
        for (int i = 0; i < n; i++) {
            String log = scanner.nextLine();
            logs.add(log);
        }
        /* 日志排序 */
        Collections.sort(logs, new Comparator<String>() {
            public int compare(String log1, String log2) {
                int time1 = convertToMillisecond(log1);
                int time2 = convertToMillisecond(log2);
                return time1 - time2;
            }
        });
        for (String log : logs) {
            System.out.println(log);
        }
    }
}

import java.util.*;   

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);   
        String s = sc.nextLine();   

        // 使用正则表达式检查输入字符串是否只包含数字和空格
        // 如果字符串中包含非法字符（非数字或空格），则输出"[]"并退出程序
        if (!s.matches("[0-9\\s]+")) {
            System.out.println("[]");
            return;
        }

        // 将输入字符串按空格分割，并将每个部分转换为整数，存储在数组heights中
        int[] heights = Arrays.stream(s.split(" ")).mapToInt(Integer::parseInt).toArray();

        // 初始化两个指针i和j，分别指向相邻的两个小朋友
        int i = 0, j = 1;

        // 遍历数组，调整相邻小朋友的身高顺序以满足"高矮交替"的要求
        while (j < heights.length) {
            // 判断当前两个相邻小朋友的身高是否满足要求
            // 条件解释：如果heights[i] > heights[j]且i是偶数，或者heights[i] < heights[j]且i是奇数
            // 则需要交换heights[i]和heights[j]的值，以符合"高矮交替"的规则
            if (heights[i] != heights[j] && (heights[i] > heights[j]) != (i % 2 == 0)) {
                // 交换heights[i]和heights[j]的值
                int tmp = heights[i];
                heights[i] = heights[j];
                heights[j] = tmp;
            }

            // 移动指针，检查下一个相邻的小朋友
            i++;
            j++;
        }

        // 使用StringJoiner将排序后的身高数组转换为字符串，并以空格分隔
        StringJoiner sj = new StringJoiner(" ");
        for (int h : heights) {  // 遍历heights数组中的每一个元素
            sj.add(String.valueOf(h));  // 将元素转换为字符串并添加到StringJoiner中
        }
        // 输出最终排序结果
        System.out.println(sj.toString());
    }
}

import java.util.*;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    String str = sc.nextLine();
    Integer[] arr = Arrays.stream(str.split(" ")).map(Integer::parseInt).toArray(Integer[]::new);

    System.out.println(getResult(arr));
  }

  public static String getResult(Integer[] arr) {
    HashMap<Integer, Integer> card = new HashMap<>();

    // 统计各种牌面的数量
    for (Integer num : arr) {
      if (card.containsKey(num)) {
        int val = card.get(num);
        card.put(num, ++val);
      } else {
        card.put(num, 1);
      }
    }

    // 统计组合，4代表炸弹，3+2代表葫芦，3代表三张，2代表对子，1代表单张
    HashMap<String, LinkedList<Integer[]>> combine = new HashMap<>();
    combine.put("4", new LinkedList<Integer[]>());
    combine.put("3+2", new LinkedList<Integer[]>());
    combine.put("3", new LinkedList<Integer[]>());
    combine.put("2", new LinkedList<Integer[]>());
    combine.put("1", new LinkedList<Integer[]>());

    // 首先将初始组合统计出来
    Set<Integer> cardKeys = card.keySet();
    for (Integer num : cardKeys) {
      switch (card.get(num)) {
        case 3:
          combine.get("3").add(new Integer[] {num});
          break;
        case 2:
          combine.get("2").add(new Integer[] {num});
          break;
        case 1:
          combine.get("1").add(new Integer[] {num});
          break;
        default:
          combine
              .get("4")
              .add(
                  new Integer[] {
                    num, card.get(num)
                  }); // 由于炸弹可能有4张以上相同牌面组成，因此既需要统计牌面num，也需要统计牌数card[num]
      }
    }

    // 炸弹排序
    combine.get("4").sort((a, b) -> !Objects.equals(a[1], b[1]) ? b[1] - a[1] : b[0] - a[0]);

    // 三张排序，牌面值越大，三张越大
    combine.get("3").sort((a, b) -> b[0] - a[0]);

    // 对子排序，牌面值越大，对子越大
    combine.get("2").sort((a, b) -> b[0] - a[0]);

    // 尝试组合出葫芦
    while (combine.get("3").size() > 0) {
      // 如果对子用完，三张还有一个，那么可以直接结束循环
      if (combine.get("2").size() == 0 && combine.get("3").size() == 1) break;

      // 否则，选取一个最大的三张
      Integer san_top = combine.get("3").removeFirst()[0];

      Integer tmp;
      // 如果此时没有对子了，胡总和第二大的三张的牌面，比最大的对子牌面大，则可以拆分三张，组合出葫芦
      if (combine.get("2").size() == 0
          || (combine.get("3").size() > 0
              && combine.get("3").get(0)[0] > combine.get("2").get(0)[0])) {
        tmp = combine.get("3").removeFirst()[0];
        // 拆分三张为对子的话，会多出一个单张
        combine.get("1").add(new Integer[] {tmp});
      } else {
        // 如果对子牌面比三张大，则不需要拆分三张，直接使用对子组合出葫芦
        tmp = combine.get("2").removeFirst()[0];
      }
      combine.get("3+2").add(new Integer[] {san_top, tmp}); // 葫芦元素含义：[三张牌面，对子牌面]
    }

    // 处理完葫芦后，就可以对单张进行降序了（因为组合葫芦的过程中，可能产生新的单张，因此单张排序要在葫芦组合得到后进行）
    combine.get("1").sort((a, b) -> b[0] - a[0]);

    // ans存放题解
    ArrayList<Integer> ans = new ArrayList<>();

    // 首先将炸弹放到ans中
    for (Integer[] vals : combine.get("4")) {
      int score = vals[0];
      int count = vals[1];
      for (int i = 0; i < count; i++) {
        ans.add(score);
      }
    }

    // 然后将葫芦放大ans中
    for (Integer[] vals : combine.get("3+2")) {
      int san = vals[0];
      int er = vals[1];
      for (int i = 0; i < 3; i++) ans.add(san);
      for (int i = 0; i < 2; i++) ans.add(er);
    }

    // 之后将三张放到ans中
    for (Integer[] vals : combine.get("3")) {
      for (int i = 0; i < 3; i++) ans.add(vals[0]);
    }

    // 接着是对子放到ans中
    for (Integer[] vals : combine.get("2")) {
      for (int i = 0; i < 2; i++) ans.add(vals[0]);
    }

    // 最后是单张放到ans中
    for (Integer[] vals : combine.get("1")) {
      ans.add(vals[0]);
    }

    StringJoiner sj = new StringJoiner(" ");
    for (Integer an : ans) {
      sj.add(an + "");
    }

    return sj.toString();
  }
}

import java.util.Arrays;
import java.util.HashMap;
import java.util.Scanner;
import java.util.StringJoiner;

public class Main {
  // 输入获取
  public static void main(String[] args) {
    // 将输入分隔符设置为“,”或者换行
    Scanner sc = new Scanner(System.in).useDelimiter("[,\n]");

    int m = sc.nextInt();
    int n = sc.nextInt();

    int[][] scores = new int[m][n];
    for (int i = 0; i < m; i++) {
      for (int j = 0; j < n; j++) {
        scores[i][j] = sc.nextInt();
      }
    }

    System.out.println(getResult(m, n, scores));
  }

  // 算法入口
  public static String getResult(int m, int n, int[][] scores) {
    if (m < 3 || m > 10 || n < 3 || n > 100) return "-1";

    HashMap<Integer, Integer[]> players = new HashMap<>();

    for (int j = 0; j < n; j++) { // 列
      Integer[] player = new Integer[m];
      for (int i = 0; i < m; i++) { // 行
        if (scores[i][j] > 10 || scores[i][j] < 1) return "-1"; // 队员得分1~10合法，否则不合法
        player[i] = scores[i][j];
      }
      Arrays.sort(player, (a, b) -> b - a); // 将每个队员的得分降序
      players.put(j, player);
    }

    StringJoiner sj = new StringJoiner(",");

    players.entrySet().stream()
        .sorted(
            (a, b) -> {
              Integer[] playerA = a.getValue();
              Integer[] playerB = b.getValue();

              int sumA = sum(playerA);
              int sumB = sum(playerB);

              if (sumA != sumB) { // 按总分降序
                return sumB - sumA;
              }

              for (int i = 0; i < m; i++) {
                if (playerA[i] == playerB[i]) continue;
                return playerB[i] - playerA[i]; // 按最高分降序
              }

              return 0;
            })
        .limit(3)
        .forEach(p -> sj.add(p.getKey() + 1 + ""));

    return sj.toString();
  }

  public static int sum(Integer[] arr) {
    return Arrays.stream(arr).reduce(Integer::sum).orElse(0);
  }
}

