function getResult(cmds) {
  let size = 0;
  let isSorted = true;
  let count = 0;

  for (let i = 0; i < cmds.length; i++) {
    const cmd = cmds[i];
    if (cmd.startsWith("head add")) {
      if (size && isSorted) isSorted = false;
      size++;
    } else if (cmd.startsWith("tail add")) {
      size++;
    } else {
      if (!size) continue;
      if (!isSorted) {
        count++;
        isSorted = true;
      }
      size--;
    }
  }

  return count;
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Scanner;
import java.util.StringJoiner;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    int[] pubArr = Arrays.stream(sc.nextLine().split(" ")).mapToInt(Integer::parseInt).toArray();
    int[] subArr = Arrays.stream(sc.nextLine().split(" ")).mapToInt(Integer::parseInt).toArray();

    getResult(pubArr, subArr);
  }

  public static void getResult(int[] pubArr, int[] subArr) {
    int n = pubArr.length;
    int m = subArr.length;

    // 将第一行输入两个一组，收集到：发布者数组中
    int[][] publisher = new int[n / 2][];
    for (int i = 0, k = 0; i < n; i += 2) {
      publisher[k++] = new int[] {pubArr[i], pubArr[i + 1]}; // [发布时刻， 发布内容]
    }

    // 将第二行输入两个一组，收集到：订阅者数组中
    int[][] subscriber = new int[m / 2][];
    for (int j = 0, k = 0; j < m; j += 2) {
      subscriber[k++] = new int[] {subArr[j], subArr[j + 1]}; // [订阅时刻， 取消订阅时刻]
    }

    // 按照发布时刻升序：发布者数组
    Arrays.sort(publisher, (a, b) -> a[0] - b[0]);

    // 为每一个订阅者构造一个的订阅内容集合
    ArrayList<ArrayList<Integer>> subContent = new ArrayList<>();
    for (int j = 0; j < subscriber.length; j++) subContent.add(new ArrayList<>());

    // 遍历发布者
    for (int[] pub : publisher) {
      int pubTime = pub[0]; // 发布时刻
      int pubContent = pub[1]; // 发布内容

      // 倒序遍历订阅者，因为后面的订阅者优先级更高，因此倒序可以实现高优先级的订阅者先匹配到发布者
      for (int j = subscriber.length - 1; j >= 0; j--) {
        int subTime = subscriber[j][0]; // 订阅时刻
        int unSubTime = subscriber[j][1]; // 取消订阅时刻

        // 如果 订阅时刻 <= 发布时刻 < 取消订阅时刻
        if (pubTime >= subTime && pubTime < unSubTime) {
          // 那么该订阅者就可以收到发布的内容
          subContent.get(j).add(pubContent);
          // 题目说，发布内容只会被最高优先级的订阅者收到
          break;
        }
      }
    }

    // 打印
    for (ArrayList<Integer> contents : subContent) {
      if (contents.size() == 0) {
        System.out.println("-1");
      } else {
        StringJoiner sj = new StringJoiner(" ");
        for (Integer content : contents) sj.add(content + "");
        System.out.println(sj.toString());
      }
    }
  }
}

import java.util.*;
import java.util.stream.Collectors;

public class Main {
    // 静态初始化一个用于映射扑克牌面到数字的HashMap，以方便后续比较大小
    private static final Map<String, Integer> CARD_TO_NUMBER;

    static {
        // 初始化HashMap
        CARD_TO_NUMBER = new HashMap<>();
        // 将每张扑克牌对应的面值映射到一个整数，其中2被认为是最大的牌
        CARD_TO_NUMBER.put("3", 3);
        CARD_TO_NUMBER.put("4", 4);
        CARD_TO_NUMBER.put("5", 5);
        CARD_TO_NUMBER.put("6", 6);
        CARD_TO_NUMBER.put("7", 7);
        CARD_TO_NUMBER.put("8", 8);
        CARD_TO_NUMBER.put("9", 9);
        CARD_TO_NUMBER.put("10", 10);
        CARD_TO_NUMBER.put("J", 11);
        CARD_TO_NUMBER.put("Q", 12);
        CARD_TO_NUMBER.put("K", 13);
        CARD_TO_NUMBER.put("A", 14);
        CARD_TO_NUMBER.put("2", 16);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);  // 创建Scanner对象用于读取输入
        String[] cards = sc.nextLine().split(" ");  // 读取一行输入，并按空格分割成数组
        // 对输入的扑克牌按照定义的牌面大小进行排序
        Arrays.sort(cards, (a, b) -> CARD_TO_NUMBER.get(a) - CARD_TO_NUMBER.get(b));

        ArrayList<LinkedList<String>> straights = new ArrayList<>();  // 用于存储所有可能的顺子序列
        LinkedList<String> currentStraight = new LinkedList<>();  // 初始化当前正在检查的顺子序列
        currentStraight.add(cards[0]);  // 将排序后的第一张牌加入到当前顺子序列中
        straights.add(currentStraight);  // 将当前顺子序列加入到顺子列表中

        // 从第二张牌开始遍历所有牌
        for (int i = 1; i < cards.length; i++) {
            String card = cards[i];
            boolean added = false;  // 标记当前牌是否已被添加到某个顺子中

            // 遍历当前已存在的所有顺子序列，尝试将当前牌加入
            for (LinkedList<String> straight : straights) {
                // 判断当前牌是否可以追加到顺子的末尾
                if (CARD_TO_NUMBER.get(card) - CARD_TO_NUMBER.get(straight.getLast()) == 1) {
                    straight.add(card);
                    added = true;
                    break;
                }
            }

            // 如果当前牌没有加入到任何顺子中，创建一个新的顺子序列
            if (!added) {
                LinkedList<String> newStraight = new LinkedList<>();
                newStraight.add(card);
                straights.add(newStraight);
            }
        }

        // 筛选出长度至少为5的有效顺子序列
        List<LinkedList<String>> validStraights =
            straights.stream().filter(straight -> straight.size() >= 5).collect(Collectors.toList());

        // 如果没有找到有效的顺子序列，输出"No"
        if (validStraights.isEmpty()) {
            System.out.println("No");
        } else {
            // 将所有有效的顺子按照起始牌的大小进行排序并输出
            validStraights.stream()
                .sorted((a, b) -> CARD_TO_NUMBER.get(a.getFirst()) - CARD_TO_NUMBER.get(b.getFirst()))
                .forEach(straight -> System.out.println(String.join(" ", straight)));
        }
    }
}

import java.util.HashMap;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        // 创建一个Scanner对象，用于读取输入
        Scanner sc = new Scanner(System.in);

        // 读取输入的打乱字符的字符串
        String s = sc.next();
        // 读取输入的正整数序列的长度
        int k = sc.nextInt();

        // 创建一个HashMap，用于统计打乱字符的字符串中各字符的数量
        HashMap<Character, Integer> base = new HashMap<>();
        // 遍历打乱字符的字符串
        for (int i = 0; i < s.length(); i++) {
            // 获取字符串中的字符
            char c = s.charAt(i);
            // 将字符及其数量存入HashMap
            base.put(c, base.getOrDefault(c, 0) + 1);
        }

        // 初始化滑动窗口的起始位置
        int i = 1;
        // 当滑动窗口的起始位置小于等于1000减去序列长度加1时，继续循环
        while (i <= 1000 - k + 1) {
            // 创建一个HashMap，用于计算滑动窗口内各字符的数量
            HashMap<Character, Integer> count = new HashMap<>();
            // 遍历滑动窗口内的正整数
            for (int j = i; j < i + k; j++) {
                // 将正整数转换为字符串
                String num = String.valueOf(j);
                // 遍历正整数字符串中的字符
                for (int m = 0; m < num.length(); m++) {
                    // 获取正整数字符串中的字符
                    char c = num.charAt(m);
                    // 将字符及其数量存入HashMap
                    count.put(c, count.getOrDefault(c, 0) + 1);
                }
            }

            // 初始化一个布尔变量，用于判断滑动窗口内各字符数量是否与打乱字符的字符串中各字符数量一致
            boolean isMatch = true;
            // 遍历打乱字符的字符串中的字符
            for (Character c : base.keySet()) {
                // 如果滑动窗口内的字符数量与打乱字符的字符串中的字符数量不一致，将isMatch设为false并跳出循环
                if (!count.containsKey(c) || count.get(c) - base.get(c) != 0) {
                    isMatch = false;
                    break;
                }
            }

            // 如果滑动窗口内各字符数量与打乱字符的字符串中各字符数量一致，则输出滑动窗口的起始位置并返回
            if (isMatch) {
                System.out.println(i);
                return;
            }

            // 更新滑动窗口的起始位置
            i++;
        }
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        // 创建一个扫描器对象，用于读取输入
        Scanner scanner = new Scanner(System.in);

        // 读取总共的胡杨树数量
        int total = scanner.nextInt();

        // 读取未成活的胡杨树数量
        int deadCount = scanner.nextInt();

        // 创建一个数组来表示每棵树是否成活，0表示成活，1表示未成活
        int[] nums = new int[total];

        // 初始化数组，所有元素设为0，表示所有树最初都是成活的
        Arrays.fill(nums, 0);

        // 根据输入，将未成活的树的位置标记为1
        for (int i = 0; i < deadCount; i++) {
            int num = scanner.nextInt();
            nums[num - 1] = 1; // 树的编号从1开始，因此需要减1
        }

        // 读取可以补种的树的数量
        int supplementCount = scanner.nextInt();

        // 初始化滑动窗口的左右边界
        int left = 0;
        int maxLen = 0; // 用于存储最大连续成活区域的长度
        int sumLeft = 0; // 滑动窗口左边界的未成活树数量
        int sumRight = 0; // 滑动窗口右边界的未成活树数量

        // 遍历所有的树，right代表滑动窗口的右边界
        for (int right = 0; right < total; right++) {
            sumRight += nums[right]; // 更新右边界的未成活树数量

            // 如果窗口内的未成活树数量大于可以补种的数量
            while (sumRight - sumLeft > supplementCount) {
                sumLeft += nums[left]; // 缩小窗口，左边界右移
                left++;
            }

            // 更新最大成活区域的长度
            maxLen = Math.max(maxLen, right - left + 1);
        }

        // 输出最大连续成活区域的长度
        System.out.println(maxLen);
    }
}

