    int end = bin.length();
    while (end - 7 > 0) {
      ans.append(getHexString("1" + bin.substring(end - 7, end)));
      end -= 7;
    }

    if (end >= 0) {
      ans.append(getHexString(bin.substring(0, end)));
    }

    return ans.toString();
  }

