 * @param {string} bin1 可能产生错误交换的二进制
 * @param {string} bin2 不会发生错误的二进制
 */
function getResult(n, bin1, bin2) {
  // 找出bin2值为0的位，并统计对应位上bin1的值为0的有x个
  let x = 0;
  // 找出bin2值为0的位，并统计对应位上bin1的值为1的有y个
  let y = 0;
  // 统计bin1总共有多少个1
  let a = 0;
  // 统计bin1总共有多少个0
  let b = 0;

  for (let i = 0; i < n; i++) {
    if (bin1[i] == "0") {
      b++;
      if (bin2[i] == "0") x++;
    } else {
      a++;
      if (bin2[i] == "0") y++;
    }
  }

  return x * a + y * b - x * y;
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    int n = sc.nextInt();

    int[] positions = new int[n];
    for (int i = 0; i < n; i++) {
      positions[i] = sc.nextInt();
    }

    int m = sc.nextInt();

    System.out.println(getResult(n, positions, m));
  }

  public static int getResult(int n, int[] positions, int m) {
    Arrays.sort(positions);

    int min = 1, max = positions[n - 1] - positions[0];
    int ans = 0;

    while (min <= max) {
      int mid = (min + max) >> 1;

      if (check(positions, m, mid)) {
        ans = mid;
        min = mid + 1;
      } else {
        max = mid - 1;
      }
    }

    return ans;
  }

  public static boolean check(int[] positions, int m, int minDis) {
    int count = 1;

    int curPos = positions[0];
    for (int i = 1; i < positions.length; i++) {
      if (positions[i] - curPos >= minDis) {
        count++;
        curPos = positions[i];
      }
    }

    return count >= m;
  }
}

